const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const help=name=>`<button class="help" data-help="${name}" aria-label="About ${name}">?</button>`;
const steps=['Your book','Analysis','Guidelines','Repair pages','Compare','Export'];
const stepIcons=['upload','search','palette','spark','compare','download'];
const state={session:null,project:null,view:0,selected:0,version:'latest',width:1200,pdfFile:null,zipFile:null,folderFiles:null,loading:false,selectedHrefs:new Set(),filter:'',model:localStorage.getItem('studio.model')||'gpt-6.1-sol',budget:Number(localStorage.getItem('studio.budget')||20),busy:false,guidelinesDirty:false,pendingJob:null};
let toastTimer,pollTimer,renderObserver;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function request(url,{method='GET',body,raw=false}={}){const headers={};if(method!=='GET')headers['X-Studio-Token']=state.session.token;if(body&&!raw)headers['Content-Type']='application/json';const response=await fetch(url,{method,headers,body:body?(raw?body:JSON.stringify(body)):undefined});if(!response.ok){const value=await response.json().catch(()=>({}));throw Error(value.error||'Something went wrong. Please try again.');}return response;}
async function api(url,options){return (await request(url,options)).json();}
const base=()=>'/api/projects/'+state.project.id;
const money=value=>'$'+Number(value||0).toFixed(2);
const active=()=>state.project?.job?.status==='running';
const orbit=()=>'<div class="orbit" aria-hidden="true"><i></i><i></i><i></i></div>';
function illustration(type='flow'){
  if(type==='hero')return `<svg class="hero-art" viewBox="0 0 260 180" aria-hidden="true"><ellipse cx="143" cy="147" rx="99" ry="17" fill="#eee8f7"/><g transform="translate(37 19) rotate(-12 65 70)"><rect x="0" y="0" width="102" height="134" rx="14" fill="#eadff8"/><rect x="8" y="8" width="86" height="118" rx="9" fill="white"/><rect x="19" y="23" width="64" height="30" rx="6" fill="#c3abdF"/><path d="M20 66h62M20 75h50M20 84h60M20 93h42" stroke="#e0d6ed" stroke-width="4" stroke-linecap="round"/><rect x="20" y="104" width="30" height="10" rx="4" fill="#e5f2e9"/></g><g transform="translate(116 30) rotate(10 60 66)"><rect width="105" height="134" rx="14" fill="#f3d8c4"/><rect x="8" y="8" width="89" height="118" rx="9" fill="white"/><rect x="19" y="22" width="67" height="25" rx="6" fill="#ab8bd4"/><path d="M20 60h64M20 69h51" stroke="#e0d6ed" stroke-width="4" stroke-linecap="round"/><rect x="20" y="81" width="65" height="28" rx="5" fill="#d7eadf"/><path d="m30 98 11-10 9 7 10-6 15 13" fill="none" stroke="#95bca5" stroke-width="3"/></g><path d="m211 7 4 10 11 4-11 4-4 10-4-10-11-4 11-4z" fill="#c5a7e7"/><path d="m28 102 3 7 8 3-8 3-3 7-3-7-8-3 8-3z" fill="#e3be93"/><circle cx="229" cy="108" r="4" fill="#d8cae9"/></svg>`;
  const labels=type==='versions'?['Original','Version 1','Version 2']:type==='guidelines'?['Source','Guidelines','Every page']:['PDF book','Old ADT','New ADT'];
  return `<div class="help-illustration"><svg viewBox="0 0 330 150" role="img" aria-label="${labels.join(' → ')}">${[0,1,2].map((n)=>`<g transform="translate(${15+n*111} 17)"><rect width="78" height="112" rx="10" fill="${['#fff0df','#e8e1f0','#e4d8f7'][n]}"/><rect x="7" y="7" width="64" height="98" rx="6" fill="white"/><rect x="15" y="18" width="48" height="${n===1&&type==='flow'?27:19}" rx="4" fill="${n===1?'#d4c8e2':'#af91d2'}"/><path d="M15 51h48M15 60h40M15 69h45" stroke="#e2dbea" stroke-width="3" stroke-linecap="round"/><rect x="15" y="80" width="48" height="15" rx="4" fill="${n===2?'#dcefe3':'#f3ebf6'}"/>${n===2?'<circle cx="69" cy="108" r="11" fill="#7db89b"/><path d="m64 108 3 3 6-7" fill="none" stroke="white" stroke-width="2"/>':''}</g>${n<2?`<path d="M${98+n*111} 73h12m-4-4 4 4-4 4" stroke="#b9a6ce" fill="none" stroke-width="2"/>`:''}`).join('')}</svg></div><div class="help-labels">${labels.map(l=>`<span>${l}</span>`).join('')}</div>`;
}
function stepDone(i){const p=state.project;if(!p)return false;return [!!p.pdf?.pages.length,!!p.pdf?.pages.length&&p.observations.length===p.pdf.pages.length,!!p.guidelines,Object.keys(p.decisions).some(h=>p.decisions[h].decision),p.pages.every(page=>p.decisions[page.href]?.humanReviewed&&p.decisions[page.href].reviewedRevision===p.revision),false][i];}
function canView(i){const p=state.project;return i===0||!!p&&(i===1||i===4||i===5||i===2&&(!!p.guidelines||stepDone(1))||i===3&&!!p.guidelines);}
function setView(i){if(state.guidelinesDirty&&$('#guideline-form')){safe(async()=>{await saveGuidelines();setView(i);});return;}if(!canView(i)){toast('Complete the previous step first.');return;}if(i===4&&state.view!==4)state.version='latest';state.view=i;state.filter='';render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){renderObserver?.disconnect();const p=state.project;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-action="home"><img src="/mark.svg" alt=""><span>adt <em>studio</em></span></a><button class="project-chip" data-action="projects"><span class="thumb">${icon('book')}</span><span><strong>${esc(p?.name||'Your next great book')}</strong><small>${p?`${p.pages.length} sections · saved locally`:'A fresh beginning'}</small></span></button><div class="nav-label">YOUR WORKFLOW</div><nav class="steps" aria-label="Book workflow">${steps.map((name,i)=>`<button class="step ${state.view===i?'active':''} ${stepDone(i)?'done':''}" data-step="${i}" ${!canView(i)?'disabled':''} ${state.view===i?'aria-current="step"':''} title="${name}"><span class="step-number">${stepDone(i)?icon('check'):String(i+1).padStart(2,'0')}</span><span class="step-label">${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="soft-note">${icon('shield')}<strong>Your book, in good hands</strong><small>Originals always kept safe.</small></div><div class="subnav"><button data-action="projects">${icon('folder')}<span>My books</span></button><button data-action="settings">${icon('settings')}<span>Settings</span></button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><span>Your workspace</span>${icon('chevron')}<strong>${steps[state.view]}</strong></div><div class="top-actions"><button class="connection" data-action="key"><i class="dot ${state.session.connected?'connected':''}"></i>${state.session.connected?'OpenAI connected':'Connect OpenAI'}${icon('key')}</button><span class="avatar">you</span></div></header><div class="content ${state.view===4?'compare-content':''}" id="view">${[uploadView,analysisView,guidelinesView,repairView,compareView,exportView][state.view]()}</div></main></div><div id="job-dock"></div>`;bindView();renderDock();if(state.view===4)sizeFrames();}
function uploadView(){const hasZip=state.zipFile||state.folderFiles;return `<section class="hero"><div class="headline"><span class="eyebrow">${icon('spark')} A little care. A better book.</span><h1>Bring your book<br><em>back to its best.</em></h1><span class="subtitle">Your original PDF. Your extracted ADT.<br>Beautiful pages, working activities, one happy book.</span></div>${illustration('hero')}</section><div class="section-heading"><h2>Start with your two files</h2><small>Everything starts here ${help('files')}</small></div><div class="upload-grid"><article class="upload-card" data-drop="zip"><div class="card-top"><strong><span class="tiny-number">1</span>ADT extraction</strong><span class="file-tag">.ZIP</span></div><label class="drop-zone" for="zip-input"><span class="file-symbol ${hasZip?'success-symbol':''}">${icon(hasZip?'check':'book')}</span><strong class="selected-file">${esc(state.zipFile?.name||state.folderFiles?.[0]?.webkitRelativePath.split('/')[0]||'Drop your ADT project')}</strong><small>${hasZip?'Ready to meet its original':'or <span class="browse-text">browse files</span>'}</small></label><input id="zip-input" class="sr-only" type="file" accept=".zip"><div class="upload-foot"><span>Your extracted, editable book</span><button class="text-button" data-action="folder">Choose folder ${icon('folder')}</button><input id="folder-input" aria-label="Choose an extracted ADT folder" class="sr-only" type="file" webkitdirectory multiple></div></article><article class="upload-card" data-drop="pdf"><div class="card-top"><strong><span class="tiny-number">2</span>Original book</strong><span class="file-tag">.PDF</span></div><label class="drop-zone pdf-zone" for="pdf-input"><span class="file-symbol ${state.pdfFile?'success-symbol':''}">${icon(state.pdfFile?'check':'pdf')}</span><strong class="selected-file">${esc(state.pdfFile?.name||'Drop the original PDF')}</strong><small>${state.pdfFile?'Our source of inspiration':'or <span class="browse-text">browse files</span>'}</small></label><input id="pdf-input" class="sr-only" type="file" accept=".pdf"><div class="upload-foot"><span>The reference for every little detail</span>${help('source')}</div></article></div><div class="action-bar"><span class="quiet">${icon('lock')} Files stay in your local workspace</span><button class="button primary" data-action="import" ${!hasZip||!state.pdfFile||state.loading?'disabled':''}>${state.loading?icon('refresh','spinner'):''}${state.loading?'Opening your book…':'Let’s open your book'}${icon('arrow')}</button></div><div class="how-card"><span class="how-title">A simple path to better pages</span><div class="how-steps">${[['search','Look closely'],['palette','Make a plan'],['spark','Refine the pages'],['download','Take it with you']].map(([i,l],n)=>`${n?'<span class="how-arrow">→</span>':''}<span class="how-item"><span class="how-icon">${icon(i)}</span>${l}</span>`).join('')}</div></div>${state.session.exampleAvailable?`<div class="example-link"><span>Want to start with your sample?</span><button class="text-button" data-action="example" ${state.loading?'disabled':''}>Open Shoqëria 5A ${icon('arrow')}</button></div>`:''}<div class="footer-label">Made for the little details that make a book feel right.</div>`;}
function title(eyebrow,heading,sub,action=''){return `<div class="view-title"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><span class="subtitle">${sub}</span></div>${action}</div>`;}
function progressCard(){const j=state.project?.job;if(!j)return '';const running=j.status==='running',percent=j.total?Math.min(100,Math.round(j.progress/j.total*100)):0;return `<div class="progress-card" id="progress-card"><div class="progress-icon ${running?'':'progress-done'}">${running?orbit():icon(j.status==='completed'?'check':'pause')}</div><div class="progress-content"><h3 id="progress-message">${esc(j.message)}</h3><div class="progress-meta"><span id="progress-detail">${j.progress} / ${j.total||'…'} · ${j.type==='inventory'||j.type==='verify'?'Local checks':money(j.cost)+' used'}</span><span id="progress-percent">${percent}%</span></div><div class="progress-track"><div class="progress-fill ${running?'active':''}" style="width:${percent}%" id="progress-fill"></div></div></div><button class="button secondary small" data-action="${running?'pause':'resume'}" ${j.status==='completed'?'disabled':''}>${icon(running?'pause':'play')}${running?'Pause':j.status==='completed'?'Complete':'Resume'}</button></div>${j.error?`<div class="info-line error">${icon('info')}<span>${esc(j.error)}</span></div>`:''}`;}
function analysisView(){const p=state.project;if(!p)return empty('Your book comes first','Choose your ADT and PDF to begin.',0);const issues=p.observations.flatMap(o=>o.sections.flatMap(s=>s.issues||[])),unmapped=p.pages.filter(s=>s.mappingStatus==='uncertain').length;return title('02 · Look closely','Every page has a story.','We’ll find the details that need a little care.',help('analysis'))+`<div class="stats"><div class="stat">${icon('pdf')}<strong>${p.pdf?.pages.length||'—'}</strong><span>original pages</span></div><div class="stat">${icon('book')}<strong>${p.pages.length}</strong><span>ADT sections</span></div><div class="stat">${icon('activity')}<strong>${p.pages.filter(s=>s.controls||s.isQuiz).length}</strong><span>activity sections</span></div><div class="stat">${icon('eye')}<strong>${p.observations.length?issues.length:unmapped}</strong><span>${p.observations.length?'details to improve':'mappings to review'}</span></div></div>${progressCard()}<div class="phase-pills"><span class="${p.pdf?.pages.length?'active':''}">${icon('check')}Read the source</span><span class="${p.stage>=1?'active':''}">${icon('layers')}Connect the pages</span><span class="${p.observations.length?'active':''}">${icon('eye')}Spot the differences</span></div>${estimate('analyse',p.pdf?.pages.length||1)}<div class="toolbar"><div class="help-wrap"><h3>Your source pages</h3>${help('mapping')}</div><div class="toolbar-right"><button class="button secondary small" data-action="analyse" ${active()||!p.pdf?.pages.length?'disabled':''}>${icon('search')}${p.observations.length?'Analyse again':'Analyse with AI'}</button><button class="button primary small" data-step="2" ${!canView(2)?'disabled':''}>Create guidelines ${icon('arrow')}</button></div></div><div class="page-grid">${(p.pdf?.pages||[]).map(page=>{const o=p.observations.find(v=>v.page===page.page),count=o?.sections.reduce((n,s)=>n+s.issues.length,0);return `<button class="page-tile" data-source-page="${page.page}"><span class="page-thumb"><img src="${base()}/pdf/${page.page}?width=220" loading="lazy" alt="Source page ${page.page}"></span><span class="tile-label"><strong>Page ${page.page}</strong>${o?`<span class="badge ${count?'orange':'green'}">${count?count+' fixes':'Checked'}</span>`:''}</span><span class="tile-sub">${page.sectionHrefs.length?`${page.sectionHrefs.length} ADT section${page.sectionHrefs.length>1?'s':''}`:'Source only'}</span></button>`;}).join('')}</div>`;}
function empty(heading,sub,step=0){return `<div class="empty-state">${icon('book')}<h2>${heading}</h2><span>${sub}</span><button class="button primary" data-step="${step}">Go to ${steps[step].toLowerCase()} ${icon('arrow')}</button></div>`;}
function guidelinesView(){const p=state.project;if(!p?.guidelines)return title('03 · Set the direction','A guide made for this book.','Colors, typography, layout, and the details worth keeping.',help('guidelines'))+`<div class="card">${illustration('guidelines')}<div class="empty-state"><h2>Let the original lead the way.</h2><span>Turn the page analysis into editable guidelines.</span>${estimate('guidelines')}<button class="button primary" data-action="guidelines" ${active()?'disabled':''}>${icon('spark')}Generate guidelines</button></div></div>${active()?`<div class="spacer"></div>${progressCard()}`:''}`;const g=p.guidelines;return title('03 · Your book’s own style','A little direction. A lot of care.','Make these guidelines yours before the agent begins.',`<span class="badge purple">Revision ${p.guidelineRevision}</span>`)+`<form id="guideline-form"><div class="guideline-layout"><div class="guideline-stack"><section class="card"><div class="section-heading"><h3>The color story</h3>${help('guidelines')}</div><div class="palette">${g.palette.map((c,i)=>`<label class="swatch"><input type="color" name="color-${i}" value="${esc(c.color)}" aria-label="${esc(c.name)} color"><input class="swatch-name" name="color-name-${i}" value="${esc(c.name)}" aria-label="Color ${i+1} name"><small>${esc(c.color)}</small></label>`).join('')}</div></section><section class="card"><h3>Words with personality</h3><div class="field-grid"><label class="field"><span>Heading font</span><input name="headingFont" value="${esc(g.headingFont)}"></label><label class="field"><span>Body font</span><input name="bodyFont" value="${esc(g.bodyFont)}"></label></div><div class="spacer"></div><label class="field"><span>Typography notes</span><textarea name="typography">${esc(g.typography)}</textarea></label></section><section class="card"><h3>A place for every detail</h3><div class="field-grid">${[['layout','Page layout'],['spacing','Spacing & alignment'],['artwork','Images & artwork'],['activities','Activities & answers']].map(([key,label])=>`<label class="field"><span>${label}</span><textarea name="${key}">${esc(g[key])}</textarea></label>`).join('')}</div></section><section class="card"><h3>Your finishing touches</h3><label class="field"><span>Book rules · one per line</span><textarea name="rules" rows="5">${esc(g.rules.join('\n'))}</textarea></label><div class="families">${g.families.map(f=>`<span class="family" title="${esc(f.description)}">${esc(f.name)}</span>`).join('')}</div></section>${g.uncertainties.length?`<div class="info-line">${icon('info')}<span>${g.uncertainties.length} details need a closer look</span><button class="text-button" data-action="guideline-notes" type="button">View</button></div>`:''}</div><aside class="guide-preview"><h3>A shared visual language</h3><div class="mini-book"><div class="mini-book-head" style="background:${esc(g.palette[0]?.color||'#a58bc7')}">A lovely little chapter</div><div class="mini-book-lines"></div><div class="mini-book-image">${icon('image')}</div><div class="mini-book-lines"></div><div class="mini-book-answer">Your thoughts go here…</div></div><span class="subtitle">Style illustration<br>Your pages stay true to the PDF.</span><div class="families"><span class="family">Editable</span><span class="family">Book-specific</span></div></aside></div><div class="sticky-save"><span id="guideline-save-label">${icon('check')} Saved in your workspace</span><div class="toolbar-right"><button type="submit" class="button secondary small">${icon('save')}Save guidelines</button><button type="button" class="button primary small" data-action="next-repair">Repair pages ${icon('arrow')}</button></div></div></form>`;}
function repairView(){const p=state.project;if(!p?.guidelines)return empty('A direction for your book','Generate your guidelines before repairing pages.',2);const rows=p.pages.filter(s=>!state.filter||s.title.toLowerCase().includes(state.filter)||s.href.toLowerCase().includes(state.filter));return title('04 · Make it shine','Better, one page at a time.','The agent inspects, edits, renders, and checks its own work.',help('repair'))+`<div class="repair-layout"><div><div class="toolbar"><label class="check-row"><input type="checkbox" id="select-all" ${state.selectedHrefs.size===p.pages.length?'checked':''}>All sections</label><input class="search" id="page-search" placeholder="Find a page…" value="${esc(state.filter)}" aria-label="Find a section"></div><div class="selection-list">${rows.map(s=>{const d=p.decisions[s.href],issues=p.observations.flatMap(o=>o.sections).find(o=>o.href===s.href);return `<label class="selection-row"><input type="checkbox" data-href="${esc(s.href)}" ${state.selectedHrefs.has(s.href)?'checked':''}><span class="page-number">${s.sourcePage||'–'}</span><span class="row-copy"><strong>${esc(s.title)}</strong><small>${esc(s.href)} · ${s.isQuiz?'Quiz':s.controls?'Activity':'Reading'}</small></span><span class="badge ${d?.decision==='review'||issues?.action==='review'?'orange':d?'green':''}">${d?({edit:'Refined',keep:'Kept',review:'Review',remove:'Removed',add:'Added'}[d.decision]||'Reviewed'):issues?.action==='edit'?'To refine':issues?.action==='keep'?'Looks good':'Ready'}</span></label>`;}).join('')}</div></div><aside class="card repair-config"><h3>A little guidance ${help('agent')}</h3><label class="field"><span>Anything to focus on?</span><textarea id="repair-prompt" placeholder="Match the PDF’s spacing. Keep the activities easy to use." rows="4"></textarea></label><label class="field"><span>Repair model</span>${modelSelect('repair-model')}</label><label class="field"><span>Run budget · USD</span><input id="repair-budget" type="number" min="1" max="500" value="${state.budget}"></label><div class="estimate"><strong id="selected-count">${state.selectedHrefs.size} sections selected</strong><span>Source → edit → render → check</span><span>Stops at your spend limit ${help('budget')}</span></div><div id="repair-estimate">${estimate('repair',state.selectedHrefs.size)}</div><button class="button primary full" data-action="repair" ${active()||!state.selectedHrefs.size?'disabled':''}>${icon('spark')}Refine selected pages</button><div class="spacer"></div><span class="quiet">${icon('layers')}Every attempt saved as a version</span></aside></div>${p.job?.type==='repair'?`<div class="spacer"></div>${progressCard()}<div class="action-bar"><span class="quiet">${p.job.completed.length} sections finished</span><button class="button secondary" data-step="4">Compare pages ${icon('arrow')}</button></div>`:''}`;}
function modelSelect(id){return `<select id="${id}" name="model">${Object.entries(state.session.models).map(([id,m])=>`<option value="${id}" ${id===state.model?'selected':''}>${m.label} · $${m.input}/$${m.output} per 1M input/output tokens</option>`).join('')}</select>`;}
function previewURL(href,revision){return `${state.session.previewOrigin}/book/${state.project.id}/${revision}/${href.split('/').map(encodeURIComponent).join('/')}`;}
function compareView(){const p=state.project;if(!p)return empty('Let’s open a book first','The PDF, original, and improved page appear together.',0);state.selected=Math.min(state.selected,p.pages.length-1);const page=p.pages[state.selected],versions=p.versions[page.href]||[],version=state.version==='latest'?versions.at(-1):versions.find(v=>v.id===state.version),revision=version?.revision||p.revision,d=p.decisions[page.href],source=page.sourcePage,hasOriginal=p.originalHrefs?.includes(page.href)!==false;return title('05 · See the difference','Three views. One lovely book.','The source, the starting point, and every new possibility.',help('comparison'))+`<div class="toolbar"><div class="toolbar-left"><button class="icon-button" data-action="prev" aria-label="Previous section" ${state.selected<=0?'disabled':''}>${icon('back')}</button><select id="section-picker" class="choose-page" aria-label="Choose section">${p.pages.map((s,i)=>`<option value="${i}" ${i===state.selected?'selected':''}>${s.sourcePage?'p. '+s.sourcePage:'Activity'} · ${esc(s.title)}</option>`).join('')}</select><button class="icon-button" data-action="next" aria-label="Next section" ${state.selected>=p.pages.length-1?'disabled':''}>${icon('chevron')}</button></div><div class="toolbar-right"><div class="segmented"><button data-width="1200" class="${state.width===1200?'selected':''}" aria-label="Desktop preview">${icon('desktop')}Desktop</button><button data-width="390" class="${state.width===390?'selected':''}" aria-label="Phone preview">${icon('phone')}Phone</button></div><button class="button lavender small" data-action="regenerate" ${active()?'disabled':''}>${icon('spark')}Repair this page</button></div></div><div class="compare-grid"><section class="compare-pane"><div class="pane-label pdf-label"><strong>${icon('pdf')}Original PDF</strong><span class="badge orange">${source?'Page '+source:'Unmapped'}</span></div><div class="preview-window">${source?`<img class="source-page" src="${base()}/pdf/${source}?width=1000" alt="Original PDF page ${source}">`:`<div class="empty-preview">${icon('pdf')}Choose a source page</div>`}</div><div class="pane-footer"><button class="text-button" data-action="mapping">${page.mappingConfidence===1?'Confirmed source':'Check source mapping'} ${icon('edit')}</button></div></section><section class="compare-pane"><div class="pane-label"><strong>${icon('book')}Old ADT</strong><span class="badge">Original</span></div><div class="preview-window frame-window">${hasOriginal?`<iframe title="Original ADT page" src="${previewURL(page.href,p.originalRevision)}" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer" data-book-frame="old"></iframe>`:`<div class="empty-preview">${icon('plus')}New page from the source PDF</div>`}</div><div class="pane-footer">Your untouched starting point</div></section><section class="compare-pane"><div class="pane-label new-label"><strong>${icon('spark')}New ADT</strong><span class="badge purple">${version?.kind==='candidate'?'Candidate':versions.length>1?'Refined':'Current'}</span></div><div class="preview-window frame-window"><iframe title="New ADT page" src="${previewURL(page.href,revision)}" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer" data-book-frame="new"></iframe></div><div class="pane-footer"><select id="version-select" aria-label="Preview saved version"><option value="current" ${state.version==='current'?'selected':''}>Current selected version</option>${[...versions].reverse().map(v=>`<option value="${esc(v.id)}" ${version?.id===v.id?'selected':''}>${v.kind==='original'?'Original':`Version ${versions.indexOf(v)}`} · ${esc(v.label.slice(0,45))}</option>`).join('')}</select></div></section></div><div class="comparison-notes"><section class="card"><div class="section-heading"><h3>Page versions</h3>${help('versions')}</div><div class="version-strip">${versions.length?[...versions].reverse().map(v=>`<button class="version-chip ${version?.id===v.id?'selected':''}" data-version="${esc(v.id)}"><strong>${v.kind==='original'?'Original':'Version '+versions.indexOf(v)}</strong><small>${v.kind==='selected'?'Selected':v.kind==='original'?'Kept safe':v.review?'Checked':'Candidate'}</small></button>`).join(''):`<span class="note-line">A fresh page. Its original is safely saved.</span>`}</div>${version?`<div class="action-bar"><span class="quiet">${esc(version.label.slice(0,80))}</span><button class="button lavender small" data-action="use-version">Use this version</button></div>`:''}</section><section class="card"><div class="section-heading"><h3>A closer look</h3><span class="badge ${d?.decision==='review'?'orange':'green'}">${d?.decision==='review'?'Needs review':d?.decision==='keep'?'No change needed':d?'Refined':'Ready to review'}</span></div><span class="note-line">${esc(d?.summary||p.observations.flatMap(o=>o.sections).find(s=>s.href===page.href)?.evidence||'Compare the layout and try the activities in each live preview.')}</span><div class="action-bar"><label class="check-row"><input type="checkbox" id="approve-page" ${d?.humanReviewed&&d.reviewedRevision===p.revision?'checked':''}>Looks right to me</label><button class="text-button" data-action="page-details">Details ${icon('chevron')}</button></div></section></div><div class="action-bar"><span class="quiet">${state.selected+1} of ${p.pages.length} sections ${p.retiredPages?.length?`· <button class="text-button" data-action="retired">${p.retiredPages.length} removed pages</button>`:''}</span><button class="button primary" data-step="5">Check & export ${icon('arrow')}</button></div>`;}
function exportView(){const p=state.project;if(!p)return empty('Your finished book starts here','Open the original PDF and ADT first.',0);const validation=p.validation,checked=validation?.pages.length||0,issues=validation?.pages.reduce((n,page)=>n+page.views.filter(v=>!v.passed).length+page.accessibility.violations.length+(page.views[0].activities?.rows.filter(r=>r.status!=='passed').length||0),0)||0,reviewed=p.pages.filter(page=>p.decisions[page.href]?.humanReviewed&&p.decisions[page.href]?.reviewedRevision===p.revision).length;return title('06 · Ready for its next chapter','A book you can take with you.','Check the pages. Keep every version. Download your ADT.',help('export'))+`<div class="card export-hero"><div class="export-symbol">${icon('download')}</div><h2>${validation?.status==='passed'?'The browser checks look good.':'One last look, then it’s yours.'}</h2><span class="subtitle">${validation?.status==='passed'?'Review the source comparison before your final export.':'The original reader, activities, artwork, and version history.'}</span><div class="export-actions"><button class="button secondary" data-action="verify" ${active()?'disabled':''}>${icon('check')}${checked?'Run checks again':'Check the whole book'}</button><button class="button primary" data-action="export" ${active()?'disabled':''}>${icon('download')}Download ${validation?.status==='passed'&&reviewed===p.pages.length?'verified ADT':'review copy'}</button></div></div><div class="all-results"><div class="result-card">${icon('book')}<strong>${checked} / ${p.pages.length} sections checked</strong><span>Desktop · tablet · phone</span></div><div class="result-card">${icon('activity')}<strong>${validation?issues+' findings':'Activities awaiting checks'}</strong><span>Input · feedback · persistence</span></div><div class="result-card">${icon('eye')}<strong>${reviewed} / ${p.pages.length} reviewed by you</strong><span>Visual comparison with the PDF</span></div></div>${p.job?.type==='verify'?`<div class="spacer"></div>${progressCard()}`:''}<div class="card notice-gap"><h3>Inside your download</h3><div class="status-list">${[['book','Editable ADT reader','Included'],['layers','Originals & page versions','Included'],['palette','Book guidelines','Included'],['check','Checks & remaining findings','Included']].map(([i,title,status])=>`<div class="status-row"><span>${icon(i)}${title}</span><span class="badge green">${status}</span></div>`).join('')}</div><div class="action-bar"><span class="quiet">${icon('shield')}Original uploads stay untouched</span><a class="text-button" href="${base()}/report" download>Download report ${icon('download')}</a></div></div>${validation?.status==='review'?`<div class="info-line">${icon('info')}<span>Some checks need attention. The download is labeled “needs review”.</span><button class="text-button" data-action="validation-details">View findings</button></div>`:''}`;}
function bindView(){
  $('#zip-input')?.addEventListener('change',e=>{state.zipFile=e.target.files[0];state.folderFiles=null;render();});$('#pdf-input')?.addEventListener('change',e=>{state.pdfFile=e.target.files[0];render();});$('#folder-input')?.addEventListener('change',e=>{state.folderFiles=[...e.target.files];state.zipFile=null;render();});
  $$('[data-drop]').forEach(el=>{el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('dragging');});el.addEventListener('dragleave',()=>el.classList.remove('dragging'));el.addEventListener('drop',e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(!file)return;if(el.dataset.drop==='pdf'&&/\.pdf$/i.test(file.name))state.pdfFile=file;else if(el.dataset.drop==='zip'&&/\.zip$/i.test(file.name)){state.zipFile=file;state.folderFiles=null;}else{toast('Choose a '+(el.dataset.drop==='pdf'?'PDF':'ZIP')+' file.');return;}render();});});
  $('#guideline-form')?.addEventListener('submit',e=>{e.preventDefault();safe(saveGuidelines);});$('#guideline-form')?.addEventListener('input',e=>{state.guidelinesDirty=true;$('#guideline-save-label').innerHTML='<span class="dirty-dot">●</span> Unsaved adjustments';if(e.target.type==='color')e.target.parentElement.querySelector('small').textContent=e.target.value;});
  $('#select-all')?.addEventListener('change',e=>{state.selectedHrefs=e.target.checked?new Set(state.project.pages.map(s=>s.href)):new Set();render();});$$('input[data-href]').forEach(el=>el.addEventListener('change',()=>{el.checked?state.selectedHrefs.add(el.dataset.href):state.selectedHrefs.delete(el.dataset.href);$('#selected-count').textContent=state.selectedHrefs.size+' sections selected';$('#repair-estimate').innerHTML=estimate('repair',state.selectedHrefs.size,$('#repair-model').value,Number($('#repair-budget').value));$('[data-action=repair]').disabled=active()||!state.selectedHrefs.size;}));
  $('#repair-model')?.addEventListener('change',()=>$('#repair-estimate').innerHTML=estimate('repair',state.selectedHrefs.size,$('#repair-model').value,Number($('#repair-budget').value)));$('#repair-budget')?.addEventListener('input',()=>$('#repair-estimate').innerHTML=estimate('repair',state.selectedHrefs.size,$('#repair-model').value,Number($('#repair-budget').value)));
  $('#page-search')?.addEventListener('input',e=>{const v=e.target.value.toLowerCase();$$('.selection-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(v));});
  $('#section-picker')?.addEventListener('change',e=>{state.selected=+e.target.value;state.version='latest';render();});$('#version-select')?.addEventListener('change',e=>{state.version=e.target.value;render();});$('#approve-page')?.addEventListener('change',e=>safe(async()=>{state.project=await api(base()+'/review',{method:'PUT',body:{href:state.project.pages[state.selected].href,approved:e.target.checked}});toast(e.target.checked?'Visual review saved.':'Review removed.');}));
}
function sizeFrames(){const resize=()=>$$('.frame-window').forEach(w=>{const frame=w.querySelector('iframe');if(!frame)return;const scale=w.clientWidth/state.width;frame.style.width=state.width+'px';frame.style.height=(w.clientHeight/scale)+'px';frame.style.transform=`scale(${scale})`;});renderObserver=new ResizeObserver(resize);$$('.frame-window').forEach(w=>renderObserver.observe(w));resize();}
function renderGuidelineState(){
  $('#guideline-state')?.remove();
  if(state.view!==2||!state.project)return;
  const p=state.project,j=p.job;
  if(p.guidelines){
    $('#guideline-form')?.insertAdjacentHTML('beforebegin',`<div class="guideline-state ready" id="guideline-state" role="status">${icon('check')}<strong>Guidelines ready</strong><span>${p.guidelines.palette.length} colors · revision ${p.guidelineRevision} · saved</span></div>`);
    return;
  }
  if(j?.type!=='guidelines')return;
  $('#progress-card')?.remove();
  const running=j.status==='running',paused=j.status==='paused';
  if(!running&&!paused)return;
  const button=$('[data-action="guidelines"]');
  if(button){button.disabled=running;button.dataset.action=paused?'resume':'guidelines';button.innerHTML=running?`${orbit()} Generating…`:`${icon('play')}Resume generation`;}
  $('#view .card')?.insertAdjacentHTML('afterend',`<div class="guideline-state ${paused?'stopped':'working'}" id="guideline-state" role="status">${running?orbit():icon('info')}<div><strong>${paused?'Generation stopped':'Generating guidelines'}</strong><span>${esc(paused?(j.error||'Your progress is saved.'):j.message)}</span></div><small>${j.calls||0} model call${j.calls===1?'':'s'} · ${money(j.cost)} used</small></div>`);
}
function renderDock(){const el=$('#job-dock');if(!el)return;const j=state.project?.job;el.innerHTML=j?.status==='running'&&![1,2,5].includes(state.view)?`<div class="job-dock">${orbit()}<div class="dock-copy"><strong>${esc(j.message)}</strong><small>${j.progress} / ${j.total||'…'} · ${j.type==='inventory'||j.type==='verify'?'Local processing':money(j.cost)+' used'}</small></div><button class="button secondary small" data-action="pause">${icon('pause')}Pause</button></div>`:'';renderGuidelineState();}
async function poll(){try{if(state.project){const session=await api('/api/session'),connectionChanged=state.session?.token!==session.token||state.session?.connected!==session.connected;state.session=session;const previous=state.project,newProject=await api('/api/projects/'+previous.id);state.project=newProject;state.selectedHrefs=new Set([...state.selectedHrefs].filter(h=>newProject.pages.some(p=>p.href===h)));const currentHref=newProject.pages[state.selected]?.href,versionsChanged=state.view===4&&state.version==='latest'&&currentHref&&(previous.versions[currentHref]?.at(-1)?.id!==newProject.versions[currentHref]?.at(-1)?.id);const changed=connectionChanged||previous.job?.status!==newProject.job?.status||previous.revision!==newProject.revision||previous.guidelineRevision!==newProject.guidelineRevision||versionsChanged;if(changed){if(previous.job?.status!==newProject.job?.status&&newProject.job?.status==='completed'){if(newProject.job.type==='guidelines')state.view=2;if(newProject.job.type==='repair'){state.view=4;const generatedHref=[...newProject.job.completed].reverse().find(href=>newProject.versions[href]?.some(v=>v.kind!=='original'&&v.at>=newProject.job.startedAt)),index=newProject.pages.findIndex(page=>page.href===generatedHref);if(index>=0)state.selected=index;state.version='latest';}}if(!state.guidelinesDirty)render();}else{const j=newProject.job;if(j&&$('#progress-message')){$('#progress-message').textContent=j.message;$('#progress-detail').textContent=`${j.progress} / ${j.total||'…'} · ${j.type==='inventory'||j.type==='verify'?'Local checks':money(j.cost)+' used'}`;const percent=j.total?Math.round(j.progress/j.total*100):0;$('#progress-percent').textContent=percent+'%';$('#progress-fill').style.width=percent+'%';}renderDock();}}}catch{}finally{pollTimer=setTimeout(poll,active()?1200:4000);}}
async function safe(fn){try{await fn();}catch(e){toast(e.message);state.loading=false;}}
function modal(title,sub,body,actions=''){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close">${icon('close')}</button></div><span class="modal-sub">${sub}</span><div class="modal-body">${body}</div><div class="modal-actions">${actions}</div>`;if(!el.open)el.showModal();return el;}
function showKey(){const pending=state.pendingJob;modal(pending?.type==='repair'?'Connect to refine your pages':pending?.type==='resume'?'Connect to resume your task':'A little intelligence.',pending?.type==='repair'?`${pending.settings.hrefs?.length||pending.settings.sourcePages?.length||1} selected page${(pending.settings.hrefs?.length||pending.settings.sourcePages?.length||1)===1?'':'s'} will start after you connect.`:pending?.type==='resume'?'Your saved task will resume after you connect.':'Connect your own OpenAI account.',`<label class="field"><span>OpenAI API key</span><input id="api-key" type="password" placeholder="sk-…" autocomplete="off" spellcheck="false"><small>Kept off your book and exported ZIP</small></label>${state.session.canRemember?`<label class="field"><span><input id="remember-key" type="checkbox" ${state.session.remembered?'checked':''}> Remember on this computer</span><small>Protected by your Windows account. Clear it with Disconnect.</small></label>`:''}<span class="quiet">Session-only keys clear when the app restarts.</span><label class="field"><span>Your model</span>${modelSelect('key-model')}</label><span class="modal-error" id="key-error"></span>`,`${state.session.connected?'<button class="text-button" data-action="disconnect">Disconnect</button>':''}<button class="button primary" data-action="connect">${icon('key')}Connect securely</button>`);$('#modal').dataset.kind='key';setTimeout(()=>$('#api-key')?.focus(),50);}
const HELP={files:{title:'Two files, one better book.',sub:'A matched pair is all you need.',lines:['ADT ZIP or folder: your editable extraction.','PDF: the original book it came from.','The original files are always preserved.']},source:{title:'Let the original lead.',sub:'Every detail has a reference.',lines:['The PDF guides the content, colors, and composition.','Artwork comes from the source book.','Digital activities stay interactive.']},analysis:{title:'Look. Compare. Understand.',sub:'A clear picture before the first edit.',lines:['Read every physical PDF page.','Match its sections to the extraction.','Inspect real page renders and record differences.']},mapping:{title:'One page can have many parts.',sub:'PDF pages and ADT sections are different.',lines:['A PDF page may map to several ADT sections.','Quizzes may be digital companion activities.','Confirm uncertain matches in the comparison view.']},guidelines:{title:'The book’s own design language.',sub:'A clear direction you can edit.',type:'guidelines',lines:['Colors and typography are grounded in the PDF.','Adjust the guidance before starting repairs.','Saved changes guide future generations.']},repair:{title:'An agent that checks its work.',sub:'Real edits. Real browser feedback.',lines:['Inspect the source and page files.','Rewrite layouts, restore artwork, and repair activities.','Render, test, and refine the result.']},agent:{title:'Room to do the real work.',sub:'Full page repair within a saved working copy.',lines:['The agent can edit HTML, styles, and supporting files.','Every candidate gets a saved version.','Unresolved changes stay available for review.']},budget:{title:'You set the limit.',sub:'Usage is charged to your OpenAI account.',lines:['A conservative estimate is reserved before each request.','The run pauses before exceeding its configured allowance.','Increase the budget and resume completed work.']},comparison:{title:'Three views, no guessing.',sub:'See exactly where your book is going.',lines:['PDF: the original source page.','Old ADT: your untouched extraction.','New ADT: the selected or saved candidate.']},versions:{title:'Every idea has a place.',sub:'Go back. Try again. Choose your favorite.',type:'versions',lines:['The imported original is always kept.','Each repair attempt creates a version.','Preview any version before selecting it.']},export:{title:'Everything, neatly packed.',sub:'An editable ADT ZIP with its history.',lines:['Native reader, activities, styles, and artwork.','Saved versions and editable book guidelines.','Validation results and remaining review items.']}};
function showHelp(name){const h=HELP[name]||HELP.repair;modal(h.title,h.sub,illustration(h.type||'flow')+`<div class="help-lines">${h.lines.map(line=>`<div class="help-line">${icon('check')}<span>${line}</span></div>`).join('')}</div>`,`<button class="button lavender" data-action="close">Got it ${icon('check')}</button>`);}
function savePreferences(model=state.model,budget=state.budget){state.model=model;state.budget=Number(budget);localStorage.setItem('studio.model',model);localStorage.setItem('studio.budget',String(state.budget));}
function estimate(type,count=1,model=state.model,budget=state.budget){const rate=state.session.models[model]||state.session.models['gpt-6.1-sol'],calls=type==='repair'?[count*3,count*24]:[count,count];const low=calls[0]*(6000*rate.input+1000*rate.output)/1e6,high=calls[1]*(20000*rate.input+5000*rate.output)/1e6,estimateMoney=n=>'$'+n.toFixed(n<0.01?4:2);return `<div class="estimate"><span>${calls[0]===calls[1]?calls[0]:calls.join('–')} model calls · roughly ${Math.max(1,Math.round(calls[0]/4))}–${Math.max(2,Math.round(calls[1]*1.5))} min</span><span>${estimateMoney(low)}–${estimateMoney(high)} estimated · ${money(budget)} run limit ${help('budget')}</span></div>`;}
function showSettings(){modal('Your studio settings','A model, a budget, and room to work.',`<label class="field"><span>Default model</span>${modelSelect('settings-model')}</label><label class="field"><span>Budget per run · USD</span><input id="settings-budget" type="number" min="1" max="500" value="${state.budget}"></label><span class="quiet">${icon('shield')}Books and checkpoints save automatically.</span>`,`<button class="button primary" data-action="save-settings">Save settings</button>`);}
async function runJob(type,settings={}){if(['analyse','guidelines','repair'].includes(type)){state.session=await api('/api/session');if(!state.session.connected){state.pendingJob={type,settings};showKey();return;}}state.project=await api(base()+'/jobs',{method:'POST',body:{type,settings:{model:state.model,budget:state.budget,...settings}}});render();}
async function resumeJob(){state.session=await api('/api/session');if(!state.session.connected){state.pendingJob={type:'resume'};showKey();return;}state.project=await api(base()+'/resume',{method:'POST',body:{settings:{model:state.model,budget:state.budget}}});render();}
async function importBook(){state.loading=true;render();try{let file=state.zipFile;if(state.folderFiles){const {zipSync}=await import('/vendor/fflate.mjs');const files={};for(const item of state.folderFiles)files[item.webkitRelativePath]=new Uint8Array(await item.arrayBuffer());file=new File([zipSync(files)],'ADT-project.zip');}state.project=await api('/api/projects?name='+encodeURIComponent(file.name),{method:'POST',body:file,raw:true});state.project=await api(base()+'/pdf?name='+encodeURIComponent(state.pdfFile.name),{method:'PUT',body:state.pdfFile,raw:true});localStorage.setItem('studio.project',state.project.id);state.selectedHrefs=new Set(state.project.pages.map(p=>p.href));state.view=1;await runJob('inventory');}finally{state.loading=false;render();}}
async function saveGuidelines(){const form=$('#guideline-form');if(!form)return;const data=new FormData(form),g=structuredClone(state.project.guidelines);for(const key of ['headingFont','bodyFont','typography','layout','spacing','artwork','activities'])g[key]=data.get(key);g.rules=String(data.get('rules')).split('\n').map(s=>s.trim()).filter(Boolean);g.palette=g.palette.map((c,i)=>({name:data.get('color-name-'+i),color:data.get('color-'+i)}));state.project=await api(base()+'/guidelines',{method:'PUT',body:g});state.guidelinesDirty=false;toast('Guidelines saved.');render();}
function regenerateModal(){const page=state.project.pages[state.selected];modal('Another lovely possibility.','Regenerate this page with your saved guidelines.',`<div class="modal-project">${icon('book')}<div><strong>${esc(page.title)}</strong><small>PDF page ${page.sourcePage||'unmapped'} · guidelines v${state.project.guidelineRevision}</small></div></div><label class="field"><span>What would you like to improve?</span><textarea id="regen-prompt" rows="4" placeholder="Bring the layout closer to the PDF. Keep the working activities."></textarea></label><label class="field"><span>Repair model</span>${modelSelect('regen-model')}</label><div id="regen-estimate">${estimate('repair',1)}</div><span class="quiet">${icon('layers')}Every generated version is saved.</span>`,`<button class="button secondary" data-action="close">Keep exploring</button><button class="button primary" data-action="run-regenerate">${icon('spark')}Regenerate page</button>`);}
async function projectsModal(){const projects=await api('/api/projects');modal('Your bookshelf','Pick up where you left off.',projects.length?projects.map(p=>`<button class="modal-project" data-project="${p.id}">${icon('book')}<div><strong>${esc(p.name)}</strong><small>${p.pages} sections · ${p.pdfPages} source pages</small></div>${icon('chevron')}</button>`).join(''):'<span class="note-line">Your first book is waiting to begin.</span>',`<button class="button lavender" data-action="new">${icon('plus')}New book</button>`);}
function mappingModal(){const page=state.project.pages[state.selected];modal('Find its place in the book.','Confirm the original page for this ADT section.',`<label class="field"><span>Physical PDF page</span><select id="mapping-page"><option value="">Companion activity · no printed page</option>${state.project.pdf.pages.map(p=>`<option value="${p.page}" ${p.page===page.sourcePage?'selected':''}>Page ${p.page}</option>`).join('')}</select></label><span class="note-line">${esc(page.mappingReason)}</span>`,`<button class="button primary" data-action="save-mapping">Confirm mapping</button>`);}
document.addEventListener('change',e=>{if(e.target.id==='regen-model')$('#regen-estimate').innerHTML=estimate('repair',1,e.target.value);});
document.addEventListener('click',e=>{const helpButton=e.target.closest('[data-help]');if(helpButton){e.preventDefault();showHelp(helpButton.dataset.help);return;}const retired=e.target.closest('[data-retired]');if(retired){const page=state.project.retiredPages.find(p=>p.href===retired.dataset.retired);state.retiredRestore=page;modal('Restore this checkpoint?','Later page selections will return to this saved state.',`<span class="note-line">${esc(page.title)} ? all newer versions remain in history</span>`,`<button class="button secondary" data-action="close">Keep current</button><button class="button primary" data-action="restore-retired">Restore checkpoint</button>`);return;}const step=e.target.closest('[data-step]');if(step&&!step.disabled){e.preventDefault();setView(Number(step.dataset.step));return;}const source=e.target.closest('[data-source-page]');if(source){const i=state.project.pages.findIndex(p=>p.sourcePage===Number(source.dataset.sourcePage));if(i<0){state.sourceOnlyPage=Number(source.dataset.sourcePage);modal('A source-only page','There is no mapped ADT section yet.',`<img src="${base()}/pdf/${source.dataset.sourcePage}?width=700" alt="Source-only PDF page" style="width:100%;max-height:65vh;object-fit:contain">`,`<button class="button secondary" data-action="close">Keep source only</button><button class="button primary" data-action="create-source-page">${icon('plus')}Create editable page</button>`);return;}state.selected=i;state.version='latest';setView(4);return;}const width=e.target.closest('[data-width]');if(width){state.width=Number(width.dataset.width);render();return;}const version=e.target.closest('[data-version]');if(version){state.version=version.dataset.version;render();return;}const project=e.target.closest('[data-project]');if(project){safe(async()=>{state.project=await api('/api/projects/'+project.dataset.project);localStorage.setItem('studio.project',state.project.id);state.selected=0;state.version='latest';state.selectedHrefs=new Set(state.project.pages.map(p=>p.href));state.view=state.project.stage?1:0;$('#modal').close();render();});return;}
  const button=e.target.closest('[data-action]');if(!button||button.disabled)return;e.preventDefault();safe(async()=>{switch(button.dataset.action){
    case 'home':setView(0);break;
    case 'folder':$('#folder-input').click();break;
    case 'import':await importBook();break;
    case 'example':state.loading=true;render();try{state.project=await api('/api/example',{method:'POST'});localStorage.setItem('studio.project',state.project.id);state.selectedHrefs=new Set(state.project.pages.map(p=>p.href));state.view=1;}finally{state.loading=false;render();}break;
    case 'key':state.session=await api('/api/session');showKey();break;
    case 'connect':{const key=$('#api-key').value.trim(),model=$('#key-model').value,remember=!!$('#remember-key')?.checked;button.disabled=true;button.textContent='Connecting…';try{await api('/api/key',{method:'POST',body:{key,model,remember}});}catch(error){$('#key-error').textContent=error.message;button.disabled=false;button.textContent='Connect securely';break;}$('#api-key').value='';state.session.connected=true;state.session.remembered=remember;savePreferences(model);const pending=state.pendingJob;state.pendingJob=null;$('#modal').close();render();if(pending){if(pending.type==='resume')await resumeJob();else await runJob(pending.type,pending.settings);toast(pending.type==='repair'?'Page refinement started.':'Your task is running.');}else toast('OpenAI connected. You’re ready.');break;}
    case 'disconnect':await api('/api/key',{method:'DELETE'});state.session.connected=false;state.session.remembered=false;$('#modal').close();render();toast('Key disconnected and cleared.');break;
    case 'close':$('#modal').close();break;
    case 'settings':showSettings();break;
    case 'save-settings':{const budget=Number($('#settings-budget').value);if(budget<1||budget>500)throw Error('Choose a budget from $1 to $500.');savePreferences($('#settings-model').value,budget);$('#modal').close();render();break;}
    case 'projects':await projectsModal();break;
    case 'new':state.project=null;state.view=0;state.zipFile=null;state.pdfFile=null;state.folderFiles=null;state.guidelinesDirty=false;localStorage.removeItem('studio.project');$('#modal').close();render();break;
    case 'analyse':await runJob('analyse');break;
    case 'guidelines':await runJob('guidelines');break;
    case 'next-repair':if(state.guidelinesDirty)await saveGuidelines();if(!state.selectedHrefs.size)state.selectedHrefs=new Set(state.project.pages.map(p=>p.href));setView(3);break;
    case 'guideline-notes':modal('Details worth a second look','Uncertainties from the source analysis.',`<div class="help-lines">${state.project.guidelines.uncertainties.map(s=>`<div class="help-line">${icon('info')}<span>${esc(s)}</span></div>`).join('')}</div>`);break;
    case 'repair':savePreferences($('#repair-model').value,$('#repair-budget').value);await runJob('repair',{hrefs:[...state.selectedHrefs],instructions:$('#repair-prompt').value});break;
    case 'pause':await api(base()+'/pause',{method:'POST'});toast('Pausing after the current operation.');break;
    case 'resume':await resumeJob();break;
    case 'prev':state.selected=Math.max(0,state.selected-1);state.version='latest';render();break;
    case 'next':state.selected=Math.min(state.project.pages.length-1,state.selected+1);state.version='latest';render();break;
    case 'regenerate':if(!state.project.guidelines){toast('Generate your book guidelines first.');break;}regenerateModal();break;
    case 'run-regenerate':{const instructions=$('#regen-prompt').value,model=$('#regen-model').value;savePreferences(model);$('#modal').close();await runJob('repair',{hrefs:[state.project.pages[state.selected].href],instructions});break;}
    case 'create-source-page':{if(!state.project.guidelines){toast('Generate the book guidelines first.');break;}$('#modal').close();await runJob('repair',{hrefs:[],sourcePages:[state.sourceOnlyPage],instructions:'Create an editable page from this source-only PDF page. Keep its content and artwork faithful, integrate the native reader, and do not invent lesson material.'});break;}
    case 'retired':modal('Pages kept in the archive','Removed from the reader. Still safe in your history.',`<div class="selection-list">${state.project.retiredPages.map(page=>`<div class="modal-project">${icon('layers')}<div><strong>${esc(page.title)}</strong><small>${esc(page.reason)}</small></div><button class="button secondary small" data-retired="${esc(page.href)}">Restore</button></div>`).join('')}</div>`);break;
    case 'use-version':{try{state.project=await api(base()+'/version',{method:'POST',body:{href:state.project.pages[state.selected].href,id:state.version}});state.version='current';render();toast('Page version selected.');}catch(error){modal('This version shares a change.','A later edit depends on the same shared files.',`<span class="note-line">${esc(error.message)}</span>`,`<button class="button secondary" data-action="close">Keep current</button><button class="button primary" data-action="restore-checkpoint">Restore whole checkpoint</button>`);}break;}
    case 'restore-retired':{const p=state.retiredRestore,v=(state.project.versions[p.href]||[]).find(v=>v.kind==='original');if(!v)throw Error('No original version is available.');state.project=await api(base()+'/version',{method:'POST',body:{href:p.href,id:v.id,wholeProject:true}});state.selected=0;state.version='current';$('#modal').close();render();break;}
    case 'restore-checkpoint':state.project=await api(base()+'/version',{method:'POST',body:{href:state.project.pages[state.selected].href,id:state.version,wholeProject:true}});state.version='current';$('#modal').close();render();break;
    case 'mapping':mappingModal();break;
    case 'save-mapping':state.project=await api(base()+'/mapping',{method:'PUT',body:{href:state.project.pages[state.selected].href,page:$('#mapping-page').value?Number($('#mapping-page').value):null}});$('#modal').close();render();break;
    case 'page-details':{const page=state.project.pages[state.selected],d=state.project.decisions[page.href],v=state.project.validation?.pages.find(s=>s.href===page.href);modal('Every little detail',esc(page.href),`<div class="help-lines">${(d?.issues?.length?d.issues:['No agent findings yet.']).map(s=>`<div class="help-line">${icon('info')}<span>${esc(s)}</span></div>`).join('')}<div class="help-line">${icon('activity')}<span>${v?`${v.views[0].activities.rows.length} activity checks recorded`:'Activity checks have not run.'}</span></div></div>`,`<a class="button secondary" href="${base()}/report" download>Download details</a>`);break;}
    case 'verify':await runJob('verify');break;
    case 'export':{button.disabled=true;button.textContent='Packing your book…';try{const response=await request(base()+'/export'),blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition'))?.[1]||'ADT-review.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Your book is ready to take with you.');}finally{render();}break;}
    case 'validation-details':{const v=state.project.validation,rows=[...(v.navigation?.rows||[]).filter(r=>r.status!=="passed").map(r=>({title:r.href,message:r.message||r.status})),...v.structure.errors.map(e=>({title:e.href||'Project',message:e.message})),...v.pages.flatMap(p=>[...p.views.filter(v=>!v.passed).map(v=>({title:p.href,message:`${v.width}px · ${v.blank?'Blank content ':''}${v.overflow?'Horizontal overflow ':''}${v.missingImages.length?'Missing images ':''}${v.runtimeErrors.length?'Runtime errors':''}`})),...p.views[0].activities.rows.filter(r=>r.status!=='passed').map(r=>({title:p.href,message:r.id+' · '+r.check+' · '+r.status})),...p.accessibility.violations.map(a=>({title:p.href,message:a.description}))])];modal('A few details need attention',rows.length+' findings · full details in the report',`<div class="selection-list">${rows.slice(0,80).map(r=>`<div class="issue-row"><div><strong>${esc(r.title)}</strong><span>${esc(r.message)}</span></div></div>`).join('')}</div>`,`<a class="button secondary" href="${base()}/report" download>Full report</a>`);break;}
  }});
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#modal').addEventListener('close',()=>{if($('#modal').dataset.kind==='key')state.pendingJob=null;delete $('#modal').dataset.kind;});
window.addEventListener('message',event=>{
  if(state.view!==4||!state.project||event.origin!==state.session.previewOrigin||!$$('iframe[data-book-frame]').some(f=>f.contentWindow===event.source))return;
  const message=event.data;if(message?.type!=='adt-preview-location'||message.project!==state.project.id)return;
  const next=state.project.pages.findIndex(page=>message.sectionId?page.section_id===message.sectionId:page.href===message.href);
  if(next>=0&&next!==state.selected){state.selected=next;state.version='latest';render();}
});
async function init(){try{state.session=await api('/api/session');const id=localStorage.getItem('studio.project');if(id)try{state.project=await api('/api/projects/'+id);state.view=state.project.job?.type==='guidelines'?2:state.project.stage?1:0;state.selectedHrefs=new Set(state.project.pages.map(p=>p.href));}catch{localStorage.removeItem('studio.project');}render();poll();}catch(e){$('#app').innerHTML=`<div class="empty-state"><h2>Let’s reconnect.</h2><span>${esc(e.message)}</span><button class="button primary" id="retry-connection">Reload</button></div>`;$("#retry-connection").addEventListener("click",()=>location.reload());}}
init();
